nta.declaration:
    const int NUM_ENEMIES = 2;
    const int TIMEOUT = 10;
typedef int[0, NUM_ENEMIES-1] enemy_id_t;
    const int LAST_SPAWN = 2;

    const int CIRCLE_SPEED = 1;
    const int CIRCLE_HEALTH = 10;
    const int CIRCLE_DAMAGE = 2;
    const int SQUARE_SPEED = 3;
    const int SQUARE_HEALTH = 20;
    const int SQUARE_DAMAGE = 4;

    const int BASIC_RANGE = 2;
    const int BASIC_FIRE_SPEED = 2;
    const int BASIC_DAMAGE = 2;
    const int CANNON_RANGE = 1;
    const int CANNON_FIRE_SPEED = 7;
    const int CANNON_DAMAGE = 5;
    const int SNIPER_RANGE = 4;
    const int SNIPER_FIRE_SPEED = 20;
    const int SNIPER_DAMAGE = 8;

    const int MAIN_TOWER_HEALTH = 10;

    const int MAP_WIDTH = 16;
    const int MAP_HEIGHT = 8;

    int pos[NUM_ENEMIES]        = {0,0};
    int hp[NUM_ENEMIES]         = {10,20};
    int dmg_a[NUM_ENEMIES]      = {2,4};
    int spawn_time[NUM_ENEMIES] = {0,3};
    int time_on_map[NUM_ENEMIES] = {0,0};

    int lives = 10;
    bool game_over = false;
    bool timeout_reached = false;
    broadcast chan stopTick;
    int global_clock = 0;

    typedef struct { int x; int y; } Coord;

    const int PATH_LENGTH = 23;
    const Coord path[PATH_LENGTH] = {
      {0,0},{1,0},{2,0},{3,0},{4,0},
      {4,1},{4,2},{4,3},{4,4},{5,4},
      {6,4},{7,4},{8,4},{8,5},{8,6},
      {8,7},{9,7},{10,7},{11,7},{12,7},
      {13,7},{14,7},{15,4}
    };

    const int BRANCH_POINTS = 2;
    const Coord branches[BRANCH_POINTS] = {{7,4},{10,7}};

    const int ALT_PATH1_LENGTH = 10;
    const Coord alt_path1[ALT_PATH1_LENGTH] = {
      {7,3},{7,2},{7,1},{8,1},{9,1},
      {10,1},{11,1},{12,1},{13,1},{14,1}
    };

    const int ALT_PATH2_LENGTH = 5;
    const Coord alt_path2[ALT_PATH2_LENGTH] = {
      {10,6},{10,5},{11,5},{12,5},{13,5}
    };

    int path_choice[NUM_ENEMIES] = {0,0};
    int alt_pos[NUM_ENEMIES]     = {0,0};

    const Coord mainTower = {15,4};

    int distance(int x1, int y1, int x2, int y2) {
        int dx = (x1 > x2) ? (x1 - x2) : (x2 - x1);
        int dy = (y1 > y2) ? (y1 - y2) : (y2 - y1);
        return dx + dy;
    }

    Coord get_enemy_position(int enemy_id) {
      Coord dummy = {-1,-1};
      if (hp[enemy_id] <= 0) return dummy;
      if (path_choice[enemy_id] == 0
          && pos[enemy_id] >= 0 && pos[enemy_id] < PATH_LENGTH)
        return path[pos[enemy_id]];
      if (path_choice[enemy_id] == 1
          && alt_pos[enemy_id] >= 0 && alt_pos[enemy_id] < ALT_PATH1_LENGTH)
        return alt_path1[alt_pos[enemy_id]];
      if (path_choice[enemy_id] == 2
          && alt_pos[enemy_id] >= 0 && alt_pos[enemy_id] < ALT_PATH2_LENGTH)
        return alt_path2[alt_pos[enemy_id]];
      return dummy;
    }

    //bool all_enemies_gone() {
      //int i;
      //for (i = 0; i < NUM_ENEMIES; i++) {
        //if (path_choice[i] == 0
          //  && pos[i] >= 0 && pos[i] < PATH_LENGTH) return false;
        //if (path_choice[i] == 1
          //  && alt_pos[i] >= 0 && alt_pos[i] < ALT_PATH1_LENGTH) return false;
        //if (path_choice[i] == 2
          //  && alt_pos[i] >= 0 && alt_pos[i] < ALT_PATH2_LENGTH) return false;
      //}
      //return true;
    //}

    bool all_enemies_gone() {
    int i;
    for (i = 0; i < NUM_ENEMIES; i++) {
        // Enemy is still active if it has health and is positioned
        if (hp[i] > 0) {
            if (path_choice[i] == 0 && pos[i] >= 0 && pos[i] < PATH_LENGTH) 
                return false;
            if (path_choice[i] == 1 && alt_pos[i] >= 0 && alt_pos[i] < ALT_PATH1_LENGTH) 
                return false;
            if (path_choice[i] == 2 && alt_pos[i] >= 0 && alt_pos[i] < ALT_PATH2_LENGTH) 
                return false;
        }
    }
    return true;
    }

    bool is_branch_point(int x, int y) {
      int i;
      for (i = 0; i < BRANCH_POINTS; i++) {
        if (branches[i].x == x && branches[i].y == y) return true;
      }
      return false;
    }

    void update_enemy_position(int id) {
      if (path_choice[id] == 0) {
        pos[id] = pos[id] + 1;
      } else if (path_choice[id] == 1) {
        alt_pos[id] = alt_pos[id] + 1;
      } else {
        alt_pos[id] = alt_pos[id] + 1;
      }
    }

    bool is_at_branch(int enemy_id) {
      Coord p = get_enemy_position(enemy_id);
      return is_branch_point(p.x,p.y);
    }

    bool reached_path_end(int enemy_id) {
      if (path_choice[enemy_id] == 0) {
        return pos[enemy_id] >= PATH_LENGTH - 1;
      } else if (path_choice[enemy_id] == 1) {
        return alt_pos[enemy_id] >= ALT_PATH1_LENGTH - 1;
      } else {
        return alt_pos[enemy_id] >= ALT_PATH2_LENGTH - 1;
      }
    }

    int get_enemy_speed(int enemy_id) {
      return (enemy_id < 3) ? CIRCLE_SPEED : SQUARE_SPEED;
    }

    bool can_move_forward(int enemy_id) {
      Coord p = get_enemy_position(enemy_id);
      return !is_branch_point(p.x,p.y) && !reached_path_end(enemy_id);
    }

    bool can_move(int enemy_id) {
      return hp[enemy_id] > 0
             && !is_at_branch(enemy_id)
             && !reached_path_end(enemy_id);
    }

    bool can_branch(int enemy_id) {
      return hp[enemy_id] > 0 && is_at_branch(enemy_id);
    }

    bool has_reached_end(int enemy_id) {
      return reached_path_end(enemy_id);
    }

    void mark_enemy_done(int id) {
    if (path_choice[id] == 0) {
        pos[id] = -1;
        alt_pos[id] = 0;  // Reset inactive variable
    } else {
        alt_pos[id] = -1;
        pos[id] = 0;      // Reset inactive variable
    }
    }

nta.system:
clock1 = ClockTick();
GM = GameMonitor();

E(const enemy_id_t id) = EnemyTemplate(id);

TS = TimeStopper();

system clock1, E, GM,TS;
